using System.Collections.Generic;public class Solution{public IList<IList<int>> KSmallestPairs(int[]a,int[]b,int k){var o=new List<IList<int>>();if(a.Length==0||b.Length==0)return o;var q=new PriorityQueue<(int i,int j),long>();for(int i=0;i<a.Length&&i<k;i++)q.Enqueue((i,0),(long)a[i]+b[0]);while(k-->0&&q.Count>0){var x=q.Dequeue();o.Add(new List<int>{a[x.i],b[x.j]});if(x.j+1<b.Length)q.Enqueue((x.i,x.j+1),(long)a[x.i]+b[x.j+1]);}return o;}}
